/* @lc app=leetcode id=3932 lang=kotlin */ class Solution { fun fr(r: Long, k: Int): Long = Math.pow(r.toDouble(), 1.0 / k).toLong().let { x0 -> (x0 + 2 downTo maxOf(0L, x0 - 2)).first { java.math.BigInteger.valueOf(it).pow(k) <= java.math.BigInteger.valueOf(r) } } fun cnt(r: Long, k: Int): Long = if (r < 0) 0L else fr(r, k) + 1 fun countKthRoots(l: Int, r: Int, k: Int): Int = (cnt(r.toLong(), k) - cnt(l - 1L, k)).toInt() }